{
  "name": "builder_rank_strata_noint",
  "intuition": "Build deterministic, objective-consistent winner/loser pairs by ranking each instance and pairing a few items from the head/middle/tail strata (head-vs-tail, head-vs-mid, mid-vs-tail) to get broad coverage without O(K^2) explosion or randomness.",
  "implementation_hint": {
    "expects": [
      "objective",
      "log_prob"
    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']  # [B, K], lower is better
    B, K = objective.shape

    # Avoid Python builtins that may be removed from the sandboxed eval environment.
    def _to_int(x, default):
        try:
            return x.__index__()
        except Exception:
            return default

    max_pairs_per_instance = _to_int(extra.get('max_pairs_per_instance', 8), 8)
    if max_pairs_per_instance < 1:
        max_pairs_per_instance = 1

    head_n = _to_int(extra.get('head_n', 2), 2)
    mid_n = _to_int(extra.get('mid_n', 2), 2)
    tail_n = _to_int(extra.get('tail_n', 2), 2)

    if head_n < 1:
        head_n = 1
    if mid_n < 1:
        mid_n = 1
    if tail_n < 1:
        tail_n = 1

    if head_n > K:
        head_n = K
    if mid_n > K:
        mid_n = K
    if tail_n > K:
        tail_n = K

    order = objective.argsort(dim=1, stable=True)

    pairs_b = []
    pairs_w = []
    pairs_l = []

    for b in range(B):
        ord_b = order[b]

        head = ord_b[:head_n]
        tail = ord_b[-tail_n:]

        mid_center = K // 2
        mid_start = mid_center - (mid_n // 2)
        if mid_start < 0:
            mid_start = 0
        if mid_start + mid_n > K:
            mid_start = K - mid_n
        if mid_start < 0:
            mid_start = 0
        mid = ord_b[mid_start:mid_start + mid_n]

        local = []

        def add_pair(a_idx, c_idx):
            oa = objective[b, a_idx]
            oc = objective[b, c_idx]
            if oa < oc:
                local.append((b, a_idx, c_idx))
            elif oc < oa:
                local.append((b, c_idx, a_idx))
            else:
                return

        i = 0
        limit = (head.numel() + mid.numel() + tail.numel()) * 3 + 4
        while len(local) < max_pairs_per_instance and i < limit:
            if head.numel() > 0 and tail.numel() > 0:
                add_pair(head[i % head.numel()], tail[i % tail.numel()])
                if len(local) >= max_pairs_per_instance:
                    break
            if head.numel() > 0 and mid.numel() > 0:
                add_pair(head[i % head.numel()], mid[i % mid.numel()])
                if len(local) >= max_pairs_per_instance:
                    break
            if mid.numel() > 0 and tail.numel() > 0:
                add_pair(mid[i % mid.numel()], tail[i % tail.numel()])
                if len(local) >= max_pairs_per_instance:
                    break
            i += 1

        if len(local) == 0 and K >= 2:
            found = False
            for r in range(K - 1):
                a = ord_b[r]
                for s in range(r + 1, K):
                    c = ord_b[s]
                    oa = objective[b, a]
                    oc = objective[b, c]
                    if oa < oc:
                        local.append((b, a, c))
                        found = True
                        break
                    if oc < oa:
                        local.append((b, c, a))
                        found = True
                        break
                if found:
                    break

        for (bb, ww, ll) in local:
            pairs_b.append(bb)
            pairs_w.append(ww)
            pairs_l.append(ll)

    # int64, 1D, consistent lengths
    b_idx = objective.new_tensor(pairs_b, dtype=torch.long)
    winner_idx = objective.new_tensor(pairs_w, dtype=torch.long)
    loser_idx = objective.new_tensor(pairs_l, dtype=torch.long)

    meta = {
        'builder': 'rank_strata_noint',
        'max_pairs_per_instance': max_pairs_per_instance,
        'head_n': head_n,
        'mid_n': mid_n,
        'tail_n': tail_n
    }
    return PrefBatch(mode='pairwise', pair_idx=(b_idx, winner_idx, loser_idx), weight=None, meta=meta)
"
}

