    ],
    "returns": "PrefBatch",
    "mode": "pairwise"
  },
  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']  # [B, K], lower is better
    B, K = objective.shape

    # extra may be missing; keep it deterministic and avoid any forbidden builtins.
    max_pairs_per_instance = 8
    if extra is not None:
        v = extra.get('max_pairs_per_instance', 8)
        if v is not None:
            max_pairs_per_instance = v

    # Clamp without calling int()/float().
    if max_pairs_per_instance < 1:
        max_pairs_per_instance = 1

    b_list = []
    w_list = []
    l_list = []

    for b in range(B):
        if K < 2:
            continue

        order = objective[b].argsort(stable=True)
        pairs_added = 0

        def add_pair(win_idx, lose_idx):
            nonlocal pairs_added
            if pairs_added >= max_pairs_per_instance:
                return
            # Convert 0-d tensors to Python ints without using int().
            b_list.append(b)
            w_list.append(win_idx.item())
            l_list.append(lose_idx.item())
            pairs_added = pairs_added + 1

        best = order[0]
        tail = order[-1]
        add_pair(best, tail)  # ensures at least one pair when K>=2

        if K >= 3:
            add_pair(best, order[1])
        if K >= 4:
            add_pair(best, order[K // 2])
        if K >= 5:
            add_pair(order[K // 2], tail)

        # Fill remaining budget with increasing rank gaps: best beats rank 1,2,4,8,...
        step = 1
        while pairs_added < max_pairs_per_instance and step < (K - 1):
            lose_r = step
            if lose_r >= K:
                lose_r = K - 1
            add_pair(order[0], order[lose_r])
            step = step * 2

    # Build int64 1D indices on objective's device.
    i64 = objective.new_empty((0,), dtype=objective.dtype).long().dtype

    if len(b_list) == 0:
        empty = objective.new_empty((0,), dtype=i64)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={'builder': 'rank_stratified_cap_no_int_v2', 'max_pairs_per_instance': max_pairs_per_instance}
        )

    b_idx = objective.new_tensor(b_list, dtype=i64)
    w_idx = objective.new_tensor(w_list, dtype=i64)
    l_idx = objective.new_tensor(l_list, dtype=i64)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={'builder': 'rank_stratified_cap_no_int_v2', 'max_pairs_per_instance': max_pairs_per_instance}
    )
