{
  "name": "loss_logsigmoid_001_margin_cost",
  "intuition": "Introduce a small, tunable soft margin on the preference logit that increases with the (detached) cost gap. This treats larger cost disadvantages as requiring stronger log-prob separation, while keeping gradients stable (gap is detached) and preserving the original pairwise logsigmoid structure.",
  "pseudocode": "gap = detach(cost_b - cost_a); x = alpha*scale*(lpw-lpl) - beta*gap - margin0 - margin1*softplus(gap); loss = -logsigmoid(clamp(x,-20,20))",
  "hyperparams": {
    "scale": 1.5057527233517845,
    "beta": 0.1,
    "margin0": 0.02,
    "margin1": 0.05
  },
  "operators_used": [
    "logsigmoid",
    "clamp",
    "softplus"
  ],
  "code": "def generated_loss(batch, model_output, extra):\n    lpw = batch['log_prob_w']\n    lpl = batch['log_prob_l']\n    weight = batch.get('weight', None)\n\n    alpha = float(extra.get('alpha', extra.get('hyperparams', {}).get('alpha', 1.0)))\n    hp = extra.get('hyperparams', {})\n    scale = float(hp.get('scale', 1.5057527233517845))\n    beta = float(hp.get('beta', 0.1))\n    margin0 = float(hp.get('margin0', 0.02))\n    margin1 = float(hp.get('margin1', 0.05))\n\n    cost_a = batch['cost_a']\n    cost_b = batch['cost_b']\n    gap = (cost_b - cost_a).detach()\n\n    # Soft margin increases with positive gap; for negative gap, softplus keeps it smooth.\n    margin = margin0 + margin1 * ops.softplus(gap)\n\n    x = alpha * scale * (lpw - lpl) - beta * gap - margin\n    x = ops.clamp(x, -20.0, 20.0)\n    loss = -ops.logsigmoid(x)\n\n    if weight is not None:\n        loss = loss * weight\n    return loss.mean()",
  "theoretical_basis": "",
  "metrics": {
    "hf_like_score": Infinity,
    "validation_objective": Infinity,
    "generalization_penalty": 0.0,
    "pair_count": 0
  },
  "implementation_hint": {
    "expects": {
      "batch": [
        "log_prob_w",
        "log_prob_l",
        "cost_a",
        "cost_b"
      ],
      "optional_batch": [
        "weight"
      ],
      "extra": [
