    B = int(objective.shape[0])
    K = int(objective.shape[1])

    max_pairs_per_instance = 24
    skip_neighbors = 1
    if extra is not None:
        v = extra.get('max_pairs_per_instance', None)
        if v is not None:
            max_pairs_per_instance = int(v)
        v = extra.get('skip_neighbors', None)
        if v is not None:
            skip_neighbors = int(v)

    order = objective.argsort(dim=1)  # lower is better

    b_out = []
    w_out = []
    l_out = []

    # Deterministic anchor ranks (avoid Python range; use torch arange).
    if K > 1:
        # Near-best vs tail and spaced anchors.
        anchors = torch.tensor([0, K // 4, K // 2, (3 * K) // 4, K - 1], device=device, dtype=torch.long)
        anchors = torch.unique(anchors)
        anchors, _ = torch.sort(anchors)

        for b in torch.arange(B, device=device, dtype=torch.long):
            pairs_left = int(max_pairs_per_instance)
            if pairs_left <= 0:
                continue

            # Helper implemented inline to avoid local function / nonlocal.
            # Add (rw, rl) where rw < rl (rank indices).
            def _try_add(rw, rl):
                nonlocal pairs_left
                if pairs_left <= 0:
                    return
                if int(rl) <= int(rw):
                    return
                if skip_neighbors is not None and skip_neighbors > 0:
                    if int(rl) - int(rw) <= int(skip_neighbors):
                        return
                wi = int(order[b, rw].item())
                li = int(order[b, rl].item())
                b_out.append(int(b.item()))
                w_out.append(wi)
                l_out.append(li)
                pairs_left -= 1

            # Best vs anchors (excluding self).
            for i in torch.arange(int(anchors.numel()), device=device, dtype=torch.long):
                if pairs_left <= 0:
                    break
                rl = int(anchors[i].item())
                _try_add(0, rl)

            # Mid vs tail anchors for additional coverage.
            if pairs_left > 0 and K >= 4:
                _try_add(K // 2, K - 1)
            if pairs_left > 0 and K >= 3:
                _try_add(K // 3, K - 1)

            # If still budget, add a few symmetric pairs.
            if pairs_left > 0:
                step = 2 if K >= 8 else 1
                rw_list = torch.arange(0, K, step, device=device, dtype=torch.long)
                for i in torch.arange(int(rw_list.numel()), device=device, dtype=torch.long):
                    if pairs_left <= 0:
                        break
                    rw = int(rw_list[i].item())
                    rl = int((K - 1) - rw)
                    _try_add(rw, rl)

    if (objective.numel() == 0) or (K <= 1) or (b_out == []):
        empty = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={
                'builder': 'stratified_rank_pairs_simple',
                'max_pairs_per_instance': max_pairs_per_instance,
                'skip_neighbors': skip_neighbors,
            },
        )

    b_idx = torch.tensor(b_out, device=device, dtype=torch.long).reshape(-1)
    w_idx = torch.tensor(w_out, device=device, dtype=torch.long).reshape(-1)
    l_idx = torch.tensor(l_out, device=device, dtype=torch.long).reshape(-1)

    return PrefBatch(
        mode='pairwise',
        pair_idx=(b_idx, w_idx, l_idx),
        weight=None,
        meta={
            'builder': 'stratified_rank_pairs_simple',
            'max_pairs_per_instance': max_pairs_per_instance,
            'skip_neighbors': skip_neighbors,
        },
    )
