  "code": "def generated_builder(feature_cache, extra):
    objective = feature_cache['objective']
    # lower objective is better
    if extra is None:
        extra = {}

    min_rank_gap = extra.get('min_rank_gap', 1)
    if min_rank_gap is None:
        min_rank_gap = 1
    max_pairs_per_instance = extra.get('max_pairs_per_instance', 8)
    if max_pairs_per_instance is None:
        max_pairs_per_instance = 8

    if min_rank_gap < 0:
        min_rank_gap = 0
    if max_pairs_per_instance < 0:
        max_pairs_per_instance = 0

    B = objective.shape[0]
    K = objective.shape[1]

    # order[b, r] = candidate index at rank r (0 is best)
    order = objective.argsort(dim=1)

    pairs_b = []
    pairs_w = []
    pairs_l = []

    r_best = 0
    r_mid = K // 2
    r_tail = K - 1

    for b in range(B):
        used = 0

        def add_pair(rw, rl):
            nonlocal used
            if used >= max_pairs_per_instance:
                return
            if rw < 0 or rl < 0 or rw >= K or rl >= K:
                return
            if (rl - rw) < min_rank_gap:
                return
            w = order[b, rw]
            l = order[b, rl]
            if w == l:
                return
            pairs_b.append(b)
            pairs_w.append(w)
            pairs_l.append(l)
            used = used + 1

        if K >= 2 and max_pairs_per_instance > 0:
            add_pair(r_best, r_tail)
            add_pair(r_best, r_mid)
            add_pair(r_mid, r_tail)

            i = 0
            while used < max_pairs_per_instance and i < K:
                j = (K - 1) - i
                if j <= i:
                    break
                add_pair(i, j)
                i = i + 1

    # Avoid Python builtins like len(); use list truthiness.
    if not pairs_b:
        empty = objective.new_zeros((0,), dtype=torch.long)
        return PrefBatch(
            mode='pairwise',
            pair_idx=(empty, empty, empty),
            weight=None,
            meta={
                'builder': 'rank_stratified_capped',
                'min_rank_gap': min_rank_gap,
                'max_pairs_per_instance': max_pairs_per_instance,
            },
        )

    b_idx = torch.tensor(pairs_b, device=objective.device, dtype=torch.long)
    winner_idx = torch.stack(pairs_w).to(device=objective.device, dtype=torch.long)
    loser_idx = torch.stack(pairs_l).to(device=objective.device, dtype=torch.long)

    b_idx = b_idx.reshape(-1)
    winner_idx = winner_idx.reshape(-1)
    loser_idx = loser_idx.reshape(-1)

