        return PrefBatch(mode='pairwise', pair_idx=(empty, empty, empty), weight=None, meta={'builder': 'gap_anchor_topk_pairs', 'gap_threshold': gap_thr, 'topk': k})

    # keep only pairs where the winner is an anchor
    # build a boolean map anchor_map[b, i] = True iff i is an anchor for b
    anchor_map = objective.new_zeros((B, N), dtype=torch.bool)
    anchor_map.scatter_(1, anchor_idx.to(dtype=torch.long), True)
    keep = anchor_map[b_idx, w_idx]

